raw:
{
 "summary": [
  {
   "text": "Кроссплот Пикетта — это графическое решение уравнения Арчи в логарифмических координатах для оценки водонасыщения и параметров пласта.",
   "claims": [
    "c2",
    "c3"
   ]
  },
  {
   "text": "Метод позволяет определять сопротивление пластовой воды, индекс цементации и матричные параметры по данным геофизических исследований скважин.",
   "claims": [
    "c1"
   ]
  }
 ],
 "how_it_works": [
  {
   "text": "Метод основан на зависимости истинного удельного сопротивления от пористости, водонасыщения и индекса цементации.",
   "claims": [
    "c3"
   ]
  },
  {
   "text": "Логарифмирование уравнения Арчи для водоносного интервала дает линейную зависимость между логарифмом сопротивления и логарифмом пористости.",
   "claims": [
    "c4",
    "c5"
   ]
  },
  {
   "text": "На графике водоносные точки образуют линию с наклоном минус один деленный на m и пересечением a умноженное на Rw.",
   "claims": [
    "c6"
   ]
  },
  {
   "text": "Нефтегазонасыщенные точки смещаются вправо от линии водоносного пласта пропорционально величине водонасыщения.",
   "claims": [
    "c7"
   ]
  },
  {
   "text": "Использование разности плотности или интервального времени вместо пористости позволяет подбирать матричные параметры подбором до выпрямления линии.",
   "claims": [
    "c8",
    "c9"
   ]
  }
 ],
 "steps": [
  {
   "text": "Постройте логарифмический график истинного сопротивления и пористости с рекомендуемым охватом в три и два декада.",
   "claims": [
    "c10"
   ]
  },
  {
   "text": "Проведите линию через водоносные точки для определения индекса цементации по наклону и произведения коэффициента tortuosity на Rw по пересечению.",
   "claims": [
    "c6"
   ]
  },
  {
   "text": "Рассчитайте водонасыщение точек, лежащих в стороне от линии, используя отношение сопротивлений и показатель насыщения.",
   "claims": [
    "c7",
    "c11"
   ]
  }
 ],
 "examples": [],
 "numbers": [
  {
   "text": "Для наилучшего разрешения данных рекомендуется использовать два декада для пористости от 0.01 до 1.0 и три декада для сопротивления от 0.1 до 100.",
   "claims": [
    "c10"
   ]
  }
 ],
 "formulas": [
  {
   "unit": "u132-08",
   "latex": "Rt = \\frac{a \\times R_o}{\\phi^m \\times S_w^n}",
   "vars": [
    {
     "sym": "Rt",
     "meaning": "истинное удельное сопротивление",
     "unit": ""
    },
    {
     "sym": "a",
     "meaning": "коэффициент извилистости",
     "unit": ""
    },
    {
     "sym": "Ro",
     "meaning": "сопротивление водоносной породы",
     "unit": ""
    },
    {
     "sym": "\\phi",
     "meaning": "пористость",
     "unit": ""
    },
    {
     "sym": "m",
     "meaning": "индекс цементации",
     "unit": ""
    },
    {
     "sym": "S_w",
     "meaning": "водонасыщенность",
     "unit": ""
    },
    {
     "sym": "n",
     "meaning": "показатель насыщения",
     "unit": ""
    }
   ]
  },
  {
   "unit": "u132-10",
   "latex": "\\log(R_t) = \\log(a \\times R_w) - m \\log(\\phi) - n \\log(S_w)",
   "vars": [
    {
     "sym": "Rw",
     "meaning": "удельное сопротивление пластовой воды",
     "unit": ""
    }
   ]
  },
  {
   "unit": "u133-08",
   "latex": "S_w = \\left(\\frac{R_o}{R_t}\\right)^{\\frac{1}{n}}",
   "vars": []
  }
 ],
 "misconception": null,
 "data_meaning": {
  "input": "Данные ГИС: истинное удельное сопротивление (Rt) и пористость (или члены разности плотности и интервального времени).",
  "output": "Оценки водонасыщения (Sw), сопротивления пластовой воды (Rw), индекса цементации (m) и матричных параметров.",
  "breaks": [
   {
    "text": "Главное допущение метода заключается в том, что в сравниваемых зонах параметры матрицы, a, m, n и Rw остаются постоянными.",
    "claims": [
     "c12"
    ]
   }
  ],
  "hypotheses": []
 },
 "analogy": {
  "text": "Кроссплот работает как метод главных компонент или кластеризация в логарифмическом пространстве признаков, где чистая вода задает опорную линейную границу (маифолд), а углеводороды отклоняют точки перпендикулярно ей.",
  "breaks_where": "В отличие от абстрактных фич в ML, оси кроссплота жестко фиксированы физическими уравнениями Арчи и параметрами породы."
 },
 "now_practice": [
  {
   "text": "Сегодня построение кроссплотов и подбор параметров выполняются в специализированном ПО интерпретации геофизических данных с интерактивной визуализацией.",
   "claims": []
  }
 ],
 "layers": {
  "mechanism": [
   {
    "text": "Логарифмирование уравнения Арчи преобразует нелинейную степенную зависимость в прямую линию на логарифмическом графике.",
    "claims": [
     "c4",
     "c5"
    ]
   }
  ],
  "practice": [
   {
    "text": "Исторический выбор осей был обусловлен доступностью двухдекадной и трехдекадной миллиметровой бумаги определенного формата.",
    "claims": [
     "c13"
    ]
   }
  ],
  "nuances": [
   {
    "text": "Неправильно выбранное значение матрицы приводит к искривлению линии водоносного пласта вместо ее выпрямления.",
    "claims": [
     "c9"
    ]
   }
  ],
  "deeper": [
   {
    "text": "Метод позволяет избежать использования дорогостоящих лабораторных исследований керна или локальных исторических данных для определения Rw и m.",
    "claims": [
     "c14"
    ]
   }
  ]
 },
 "glossary": [
  {
   "term": "кроссплот Пикетта",
   "en": "Pickett plot",
   "definition": "Графический метод решения уравнения Арчи в логарифмических координатах для определения насыщения и параметров пласта."
  },
  {
   "term": "линия водоносного пласта",
   "en": "water-bearing line",
   "definition": "Прямая линия на кроссплоте Пикетта, соответствующая 100% водонасыщенности."
  }
 ],
 "format_reason": "Текст с формулами и описанием графического метода отлично подходит для текстового объяснения с элементами интерактивных шагов построения.",
 "claims": [
  {
   "id": "c1",
   "kind": "observation",
   "text": "Метод оценивает водонасыщение и помогает определить Rw, m, а также матричные параметры sonic и density логов.",
   "quote": "This technique estimates water saturation and can also help determine: - formation water resistivity (Rw) - cementation factor (m) - matrix parameters for sonic and density logs",
   "unit": "u132-05"
  },
  {
   "id": "c2",
   "kind": "observation",
   "text": "Кроссплот Пикетта является одним из простейших и эффективнейших методов кроссплотов.",
   "quote": "The Pickett plot (Pickett, 1966, 1973) is one of the simplest and most effective crossplot methods in use.",
   "unit": "u132-05"
  },
  {
   "id": "c3",
   "kind": "inference",
   "text": "Метод основан на том, что Rt является функцией пористости, Sw и m, представляя графическое решение уравнения Арчи.",
   "quote": "The Pickett method is based on the observation that true resistivity (Rt) is a function of porosity (phi), water saturation (Sw), and cementation exponent (m). It is actually a graphical solution of Archie's equation",
   "unit": "u132-07"
  },
  {
   "id": "c4",
   "kind": "observation",
   "text": "Взятие логарифма от уравнения Арчи для удельного сопротивления приводит к линейному виду.",
   "quote": "Taking the logarithm of the equation produces: \\log(R_t) = \\log(a \\times R_w) - m \\log(\\phi) - n \\log(S_w)",
   "unit": "u132-09"
  },
  {
   "id": "c5",
   "kind": "observation",
   "text": "Для водоносной зоны Sw равно единице, логарифм Sw равен нулю, и уравнение упрощается.",
   "quote": "If the zone is water-bearing, Sw = 1, \\log(Sw) = 0, and the equation reduces to: \\log(R_t) = \\log(a \\times R_w) - m \\log(\\phi)",
   "unit": "u132-11"
  },
  {
   "id": "c6",
   "kind": "observation",
   "text": "Водоносные точки разной пористости образуют прямую линию с наклоном минус один деленный на m и пересечением a умноженное на Rw.",
   "quote": "Water-bearing points of different porosities plot along a straight line with a slope of (-1/m) and an intercept (at porosity = 1.0) of (a * Rw). From this line, the cementation exponent (m) can be determined",
   "unit": "u132-18"
  },
  {
   "id": "c7",
   "kind": "observation",
   "text": "Углеводородоносные точки лежат в стороне от линии, смещенные вправо по горизонтали за счет увеличенного сопротивления.",
   "quote": "Hydrocarbon-bearing points lie away from the line, moved horizontally to the right from the water-bearing line by their increased resistivity.",
   "unit": "u132-18"
  },
  {
   "id": "c8",
   "kind": "observation",
   "text": "Выражения rho_b минус rho_ma и delta_t минус delta_t_ma являются числителями в уравнениях пористости и используются как ярлыки для избежания вычисления пористости.",
   "quote": "Both quantities are the numerators in porosity equations (rho_b - rho_ma) from the density porosity equation ..., and (delta_t - delta_t_ma) from the Wyllie time-average sonic equation ... The quantities are plotting shortcuts to avoid the calculation of porosity",
   "unit": "u133-06"
  },
  {
   "id": "c9",
   "kind": "observation",
   "text": "Если матричное значение выбрано верно, линия прямая; если слишком высоко или низко — линия искривляется.",
   "quote": "If there is a range of porosities in the zones defining the water-bearing line on the Pickett plot, and if the matrix value is chosen correctly, the line is straight. If the chosen matrix value is either too high or too low, the line is curved.",
   "unit": "u133-06"
  },
  {
   "id": "c10",
   "kind": "observation",
   "text": "Лучший формат для разрешения данных — два декада для пористости от 0.01 до 1.0 и три декада для сопротивления от 0.1 до 100.",
   "quote": "The best format to use (for the best data resolution) is two decades for porosity (0.01 to 1.0, or 1% to 100%) and three decades for the resistivity (0.1 to 100, or 1 to 1000).",
   "unit": "u132-14"
  },
  {
   "id": "c11",
   "kind": "observation",
   "text": "Водонасыщение точки определяется через отношение сопротивления водоносной линии Ro к сопротивлению точки Rt в степени единицы на n.",
   "quote": "The water saturation of a point plotting away from the water-bearing line can be determined by the equation: Sw = (Ro / Rt)^(1/n)",
   "unit": "u133-07"
  },
  {
   "id": "c12",
   "kind": "assumption",
   "text": "Главное допущение интерпретации заключается в постоянстве всех параметров матрицы, a, m, n и Rw в сравниваемых зонах.",
   "quote": "The prime assumption is that in the zones being compared, all the parameters (matrix value, a, m, n, and Rw) do not change.",
   "unit": "u133-12"
  },
  {
   "id": "c13",
   "kind": "observation",
   "text": "Конвенция построения с сопротивлением на оси x и пористостью на оси y возникла из-за доступности логарифмической бумаги в момент разработки метода.",
   "quote": "In practice, the resistivity (Rt) is usually plotted on the x-axis and the porosity (phi) on the y-axis (Figure 7.4). This convention stems from the availability of full-logarithmic graph paper ... at the time Pickett developed the technique.",
   "unit": "u132-14"
  },
  {
   "id": "c14",
   "kind": "inference",
   "text": "Сила кроссплота Пикетта в том, что Rw и m можно оценить из данных, избегая локальных знаний или дорогих замеров керна.",
   "quote": "The power in the Pickett plot is that water resistivity (Rw) and cementation exponent (m) can be estimated from the data, rather than having to be derived from local knowledge or from expensive core measurements.",
   "unit": "u132-19"
  }
 ]
}
